from llama_cpp import Llama

llm = Llama(
    model_path="{{gguf_path}}",
    n_ctx={{n_ctx}},
    n_gpu_layers=-1,
)

def generate(prompt: str) -> str:
    out = llm.create_chat_completion(
        messages=[{"role": "user", "content": prompt}],
    )
    return out["choices"][0]["message"]["content"]

if __name__ == "__main__":
    print(generate("hi"))
